From 3560508d4eb85687d47b6feaa0ee393a6a0e978a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:57:01 +0100
Subject: [PATCH] libtaskmanager: keep source order when rows are inserted
 ungrouped

Rows coming back from the filter, such as windows shown again after a
desktop switch, were always appended, so with sorting disabled they ended
up after any task that stayed visible. Insert them at their source position.

BUG: 444834
---
 libtaskmanager/taskgroupingproxymodel.cpp | 9 +++++++--
 1 file changed, 7 insertions(+), 2 deletions(-)

diff --git a/libtaskmanager/taskgroupingproxymodel.cpp b/libtaskmanager/taskgroupingproxymodel.cpp
index 82709a40c9..32743d81f3 100644
--- a/libtaskmanager/taskgroupingproxymodel.cpp
+++ b/libtaskmanager/taskgroupingproxymodel.cpp
@@ -123,8 +123,13 @@ void TaskGroupingProxyModel::Private::sourceRowsInserted(const QModelIndex &pare

     for (int i = start; i <= end; ++i) {
         if (!shouldGroup || !tryToGroup(q->sourceModel()->index(i, 0))) {
-            q->beginInsertRows(QModelIndex(), rowMap.count(), rowMap.count());
-            rowMap.append(new QList<int>{i});
+            const auto it = std::find_if(rowMap.cbegin(), rowMap.cend(), [i](const QList<int> *sourceRows) {
+                return sourceRows->constFirst() > i;
+            });
+            const int row = std::distance(rowMap.cbegin(), it);
+
+            q->beginInsertRows(QModelIndex(), row, row);
+            rowMap.insert(row, new QList<int>{i});
             q->endInsertRows();
         }
     }
